std::vector<Node> path_nodes;
if (start_idx < 0 || end_idx < 0 || 
    start_idx >= graph.SNodes().size() || end_idx >= graph.SNodes().size()) {
    return path_nodes;
}

// Initialize start and end nodes
RouteModel::Node* start_node = &(graph.SNodes()[start_idx]);
RouteModel::Node* end_node = &(graph.SNodes()[end_idx]);

// Open list for A* (using multiset for automatic sorting - but we'll manage it manually)
std::vector<RouteModel::Node*> open_list;

// Setup initial state for start node
start_node->g_value = 0.0;
start_node->h_value = 0.0; // Start node heuristic is 0
start_node->visited = true;
start_node->parent = nullptr;
open_list.push_back(start_node);

// Main A* loop
while (!open_list.empty()) {
    // Get the node with the lowest f = g + h value
    std::sort(open_list.begin(), open_list.end(), [](const RouteModel::Node* a, const RouteModel::Node* b) {
        return a->get_g() < b->get_g();
    });

    RouteModel::Node* current = open_list.back();
    open_list.pop_back();

    // Process current node
    current->find_neighbors();
    current->visited = true;

    // Explore neighbors
    for (RouteModel::Node* neighbor : current->neighbors) {
        if (!neighbor->visited) {
            float tentative_g = current->g_value + current->distance(*neighbor);
            if (tentative_g < neighbor->g_value) {
                neighbor->g_value = tentative_g;
                neighbor->parent = current;
                if (!neighbor->visited) {
                    open_list.push_back(neighbor);
                }
            }
        }
    }

    // If we reached the end node, reconstruct path and return
    if (current == end_node) {
        // Reconstruct path from end to start
        while (current != nullptr) {
            path_nodes.push_back(*current);
            current = current->parent;
        }
        std::reverse(path_nodes.begin(), path_nodes.end());
        return path_nodes;
    }
}

// If we get here, no path was found
return path_nodes;

